/reference/glossary.jsonl:403:{"id": "v19/support/designed_to_be", "version": 1, "symbol": "designed_to_be", "kind": "claim_relation", "status": "Accepted", "signature": "CLAIM designed_to_be(subject: STRING / TERM, quality: STRING)", "definition": "Asserts the intended design goal, alignment quality, or persona attribute of a system. design objective.", "aliases": ["intended_to_be"], "dependencies": ["v19/support/subject"], "shared_rules": ["v19/rule/trace-relations-general"]}
/reference/glossary.jsonl:404:{"id": "v19/support/possesses", "version": 1, "symbol": "possesses", "kind": "claim_relation", "status": "Accepted", "signature": "CLAIM possesses(subject: STRING / TERM, item: TERM, value: BOOL)", "definition": "Asserts whether a subject possesses or lacks a stated property, capability, or entity. possession assertion with boolean polarity.", "aliases": ["holds_property"], "dependencies": ["v19/support/subject"], "shared_rules": ["v19/rule/trace-relations-general"]}
