/reference/glossary.jsonl:407:{"id": "v19/support/has_goal", "version": 1, "symbol": "has_goal", "kind": "claim_relation", "status": "Accepted", "signature": "CLAIM has_goal(subject: STRING / TERM, goal: TERM)", "definition": "Asserts that an entity or agent pursues a stated goal or objective. teleological claim.", "aliases": ["pursues_goal"], "dependencies": ["v19/support/subject"], "shared_rules": ["v19/rule/trace-relations-general"]}
/reference/glossary.jsonl:408:{"id": "v19/support/trained_for", "version": 1, "symbol": "trained_for", "kind": "claim_relation", "status": "Accepted", "signature": "CLAIM trained_for(subject: STRING / TERM, activity: TERM)", "definition": "Asserts that an agent or model underwent training for a designated activity. training objective.", "aliases": ["fine_tuned_for"], "dependencies": ["v19/support/subject", "v19/support/activity"], "shared_rules": ["v19/rule/trace-relations-general"]}
/reference/glossary.jsonl:409:{"id": "v19/support/meets_needs", "version": 1, "symbol": "meets_needs", "kind": "claim_relation", "status": "Accepted", "signature": "CLAIM meets_needs(subject: TERM, beneficiary: STRING / TERM)", "definition": "Asserts that an item, activity, or plan satisfies the needs of a beneficiary. utility/satisfaction claim.", "aliases": ["satisfies_needs"], "dependencies": ["v19/support/subject"], "shared_rules": ["v19/rule/trace-relations-general"]}
/reference/glossary.jsonl:414:{"id": "v19/support/leads_to", "version": 1, "symbol": "leads_to", "kind": "claim_relation", "status": "Accepted", "signature": "CLAIM leads_to(cause: TERM, effect: TERM)", "definition": "Asserts a conceptual consequence or progression from cause to effect. progression relation.", "aliases": ["results_in"], "shared_rules": ["v19/rule/trace-relations-general"]}
/reference/glossary.jsonl:415:{"id": "v19/support/important", "version": 1, "symbol": "important", "kind": "claim_relation", "status": "Accepted", "signature": "CLAIM important(target: TERM)", "definition": "Asserts that a concept, activity, or condition is important or significant. evaluative importance claim.", "aliases": ["significant"], "shared_rules": ["v19/rule/trace-relations-general"]}
/reference/glossary.jsonl:416:{"id": "v19/support/comfortable", "version": 1, "symbol": "comfortable", "kind": "claim_relation", "status": "Accepted", "signature": "CLAIM comfortable(person: TERM, value: BOOL)", "definition": "Asserts whether a person or animal is comfortable in a situation. affective/state claim.", "aliases": ["is_comfortable"], "shared_rules": ["v19/rule/trace-relations-general"]}
/reference/glossary.jsonl:423:{"id": "v19/support/unaware", "version": 1, "symbol": "unaware", "kind": "claim_relation", "status": "Accepted", "signature": "CLAIM unaware(person: STRING / TERM, topic: STRING / TERM)", "definition": "Asserts epistemic lack of awareness regarding a topic, fact, or event. epistemic state.", "aliases": ["ignorant_of"], "shared_rules": ["v19/rule/trace-relations-general"]}
/reference/glossary.jsonl:424:{"id": "v19/support/ongoing", "version": 1, "symbol": "ongoing", "kind": "claim_relation", "status": "Accepted", "signature": "CLAIM ongoing(target: TERM)", "definition": "Asserts that a conflict, process, or initiative is actively ongoing. temporal aspect claim.", "aliases": ["in_progress"], "shared_rules": ["v19/rule/trace-relations-general"]}

